{"updateComponents":{"surfaceId":"team-settings","components":[{"id":"root","component":"Stack","gap":"lg","style":{"maxWidth":"720px","marginHorizontal":"auto","padding":"$spacing.lg","width":"100%"},"children":["appbar","general-card","danger-card"]},{"id":"appbar","component":"AppBar","title":"Team settings","subtitle":{"path":"/team/name"}},{"id":"general-card","component":"Card","title":"General","description":"Basic information about your team.","children":["general-form"]},{"id":"general-form","component":"Form","name":"teamGeneral","on":{"submit":{"event":{"name":"saveTeamSettings","context":{"name":{"path":"/team/name"},"slug":{"path":"/team/slug"},"timezone":{"path":"/team/timezone"}}}}},"children":["name-input","slug-input","slug-preview","tz-select","form-actions"]},{"id":"name-input","component":"Input","label":"Team name","name":"name","value":{"path":"/team/name"},"checks":[{"condition":{"call":"required","args":{"value":{"path":"/team/name"}}},"message":"Team name is required."},{"condition":{"call":"length","args":{"value":{"path":"/team/name"},"min":2,"max":64}},"message":"Use 2 to 64 characters."}]},{"id":"slug-input","component":"Input","label":"URL slug","name":"slug","placeholder":"my-team","value":{"path":"/team/slug"},"checks":[{"condition":{"call":"required","args":{"value":{"path":"/team/slug"}}},"message":"Slug is required."},{"condition":{"call":"regex","args":{"value":{"path":"/team/slug"},"pattern":"^[a-z0-9]+(-[a-z0-9]+)*$"}},"message":"Use lowercase letters, numbers and single hyphens."},{"condition":{"call":"length","args":{"value":{"path":"/team/slug"},"min":3,"max":40}},"message":"Use 3 to 40 characters."}]},{"id":"slug-preview","component":"Text","variant":"muted","text":{"call":"concat","args":{"values":["Your team URL: https://app.yourev.at/",{"path":"/team/slug"}]}}},{"id":"tz-select","component":"Select","label":"Timezone","name":"timezone","searchable":true,"value":{"path":"/team/timezone"},"options":{"path":"/timezones"},"checks":[{"condition":{"call":"required","args":{"value":{"path":"/team/timezone"}}},"message":"Pick a timezone."}]},{"id":"form-actions","component":"Stack","direction":"horizontal","justify":"end","children":["save-btn"]},{"id":"save-btn","component":"Button","label":"Save changes","submit":true},{"id":"danger-card","component":"Card","title":"Danger zone","description":"Irreversible actions for this team.","style":{"borderColor":"$color.danger","borderWidth":"1px","borderStyle":"solid"},"children":["danger-row"]},{"id":"danger-row","component":"Stack","direction":{"base":"vertical","md":"horizontal"},"justify":"between","align":{"base":"stretch","md":"center"},"children":["danger-text","delete-dialog"]},{"id":"danger-text","component":"Stack","gap":"xs","children":["danger-title","danger-desc"]},{"id":"danger-title","component":"Text","variant":"label","text":"Delete this team"},{"id":"danger-desc","component":"Text","variant":"muted","text":"All projects, members and data will be permanently removed. This cannot be undone."},{"id":"delete-dialog","component":"AlertDialog","title":"Delete team?","description":{"call":"concat","args":{"values":["This permanently deletes “",{"path":"/team/name"},"” and all of its data. This action cannot be undone."]}},"confirmLabel":"Delete team","destructive":true,"open":{"path":"/ui/deleteOpen"},"slots":{"trigger":"delete-btn"},"on":{"confirm":{"event":{"name":"deleteTeam","context":{"teamId":{"path":"/team/id"}}}}}},{"id":"delete-btn","component":"Button","label":"Delete team","variant":"destructive","icon":"trash"}]}}
